        nFormat -= 2;

    if( (nFormat >= 0) && (nFormat < SdXMLTimeFormatCount) )
    {
        return aSdXMLFixedTimeFormats[nFormat]->maName;
    }
    else
    {
        return EMPTY_OUSTRING;
    }
}
OUString SdXMLNumberStylesExporter::getDateStyleName(const sal_Int32 nDateFormat )
{
